B=Path(__file__).resolve().parent;D=B/'2026-engine';row=next(r for r in json.loads((B/'source-index.json').read_text()) if r['target']['model_year']==2026);U=row['source_url'];P=Path(row['local_pdf_path']);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert sha(P)==row['document_sha256'];book=fitz.open(P)
