def st(i,title,t,p,rec=False):steps.append(dict(id=i,title=title,instruction=t,depends_on=[steps[-1]['id']] if steps else [],source_pdf_pages=sorted(set(p)),source_links=[U+'#page='+str(n) for n in sorted(set(p))],diagram_reference_required=True,record_required=rec,verification=['Record the actual acceptance results.' if rec else 'Confirm assembly and component accounting.']))
st('accept','Confirm original-part eligibility','Use the original stock detached head, guides and four original titanium valves only after their measured inspections have passed. Record accepted head/seat/guide/stem/runout/lifter/spring results and original positions. Any replacement valve requires guide renewal, and a valve used for lapping cannot be reused for running. Do not use this original-part route after valve lapping, guide replacement, seat machining or head replacement.',[52,228,233,234,235,236],True)
st('clean','Clean the prepared head','Clean valve stem ends and remove all inspection solvent, carbon debris and layout fluid. Check that the head and identified parts are clean, dry and undamaged. Keep each valve, spring, retainer, seat, pad and lifter assigned to its original position.',[232,234,235,236])
st('seals','Fit new seals and original valves','Lubricate each valve stem and new stem seal with molybdenum disulfide oil. Install the spring seat, new stem seal and original valve in its original location using the illustrated order. All four removed valves receive new stem seals.',[231,234,236])
st('springs','Install springs and retainers','Install each accepted original spring with its larger-pitch coils facing upward and smaller-pitch coils downward. Fit the original retainer to the corresponding valve. Compare all four assemblies with the diagram before compressing.',[236])
st('cotters','Fit both cotters per valve','Compress each spring with compressor90890-04200 / YM-04019 and attachment90890-04108 / YM-04108 (22 mm). Install the two valve cotters in their stem grooves, then release the compressor carefully. Account for all eight cotters and verify both halves are seated at every valve.',[231,236,237])
st('seat-cotters','Set the cotters','Lightly tap each valve tip with a soft-face hammer to seat the cotters as illustrated. Avoid excessive force, which can damage the valve. Recheck cotter seating and retainer capture.',[237])
st('sealing','Confirm sealing after assembly','Before fitting lifters, repeat the illustrated clean-solvent port check with the spring-held valves closed. Record the sealing result at all four seats. A leak requires further face/seat/contact-width investigation; do not accept the head for installation. Drain and dry all test solvent afterward.',[232],True)
st('pads','Install original pads and lifters','Apply engine oil to the adjusting pads and valve lifters. Protect the chain cavity from a dropped pad, then return each pad and lifter to its original identified position. Confirm each lifter rotates smoothly with a finger. Account for and remove the protective cloth.',[232,237])
st('finish','Record the assembled head','Record four accepted sealing results, eight retained cotters, four new seals, correct spring orientation and smooth lifters. Keep the assembled head clean and protected. It remains detached from the engine; cam timing, actual cold valve-clearance checks, head mounting and startup are separate operations. Resolve the head-bolt lubricant conflict before head installation.',[61,91,229,236,237],True)
d.update(id='yamaha-2026-yz250f-original-head-valve-reassembly-v1',title='Reassemble an accepted original cylinder head',entry_state=['Detached original cylinder head and individually identified original valves/guides/springs/lifters/pads, all actual inspections passed; new stem seals available.'],exit_state=['Original valve assemblies and new stem seals installed in the detached head; sealing, cotter capture and lifter movement checked.'],applicability={'included':'Exact US2026 standard YZ250F original stock head and original accepted valve-train components.','excluded':['New valves or guides, lapping, seat machining, head replacement','Head-to-cylinder mounting, cam timing, valve adjustment and startup','Other model years or modified components'],'year_inheritance':'NONE'},preflight=['Actual head/valve/guide/seat/spring/lifter inspections must be accepted before assembly.','Every original component must remain traceable to its original position.','No valve used for lapping may be returned to service. New running valves require their separate guide/seat repair route.','The head-bolt lubricant conflict affects later head mounting; this bench operation does not install those bolts.'],critical_stop_conditions=['Unidentified or rejected original part','Valve-seat leakage, cotters not seated or lifter binding','Any proposed lapping, guide renewal or new-valve substitution within this original-part scope'],required_tools=[{'name':x} for x in ['Clean bench and labeled parts tray','Valve spring compressor90890-04200 / YM-04019','22 mm compressor attachment90890-04108 / YM-04108','Soft-face hammer','Clean solvent and suitable collection tray']],required_parts=[{'name':'Four new correct stock valve stem seals'},{'name':'Molybdenum disulfide oil for valve stems/seals'},{'name':'Engine oil for pads/lifters'}],completeness='Complete bounded reassembly and sealing verification of accepted original valve assemblies in a detached head. Head mounting and engine return to service remain outside scope.',steps=steps)
